package mesh
import("math";"sort";"strings";"sync")
type RouteHop struct{PeerID string `json:"peer_id"`;Cost float64 `json:"cost"`};type RouteGraph struct{mu sync.RWMutex;edges map[string][]RouteHop}
func NewRouteGraph()*RouteGraph{return &RouteGraph{edges:make(map[string][]RouteHop)}}
func(g *RouteGraph)Connect(from string,hop RouteHop){if g==nil{return};from=strings.TrimSpace(from);hop.PeerID=strings.TrimSpace(hop.PeerID);if from==""||hop.PeerID==""||len(from)>256||len(hop.PeerID)>256||from==hop.PeerID||math.IsNaN(hop.Cost)||math.IsInf(hop.Cost,0)||hop.Cost<0{return};g.mu.Lock();defer g.mu.Unlock();if g.edges==nil{g.edges=make(map[string][]RouteHop)};for i,existing:=range g.edges[from]{if existing.PeerID==hop.PeerID{if hop.Cost<existing.Cost{g.edges[from][i]=hop};return}};g.edges[from]=append(g.edges[from],hop)}
func(g *RouteGraph)BestPath(source,destination string)([]string,float64,bool){if g==nil{return nil,0,false};source=strings.TrimSpace(source);destination=strings.TrimSpace(destination);if source==""||destination==""||len(source)>256||len(destination)>256{return nil,0,false};g.mu.RLock();edges:=make(map[string][]RouteHop,len(g.edges));for k,v:=range g.edges{edges[k]=append([]RouteHop(nil),v...)};g.mu.RUnlock();dist:=map[string]float64{source:0};prev:=map[string]string{};visited:=map[string]bool{};for{current:="";best:=0.0;for node,d:=range dist{if !visited[node]&&(current==""||d<best||(d==best&&node<current)){current,best=node,d}};if current==""||current==destination{break};visited[current]=true;for _,edge:=range edges[current]{candidate:=best+edge.Cost;old,ok:=dist[edge.PeerID];if !ok||candidate<old||(candidate==old&&current<prev[edge.PeerID]){dist[edge.PeerID]=candidate;prev[edge.PeerID]=current}}};cost,ok:=dist[destination];if !ok{return nil,0,false};path:=[]string{destination};for path[len(path)-1]!=source{p,ok:=prev[path[len(path)-1]];if !ok{return nil,0,false};path=append(path,p)};for i,j:=0,len(path)-1;i<j;i,j=i+1,j-1{path[i],path[j]=path[j],path[i]};return path,cost,true}
func(g *RouteGraph)Peers(node string)[]RouteHop{if g==nil{return []RouteHop{}};node=strings.TrimSpace(node);if node==""||len(node)>256{return []RouteHop{}};g.mu.RLock();out:=append([]RouteHop(nil),g.edges[node]...);g.mu.RUnlock();sort.SliceStable(out,func(i,j int)bool{if out[i].Cost!=out[j].Cost{return out[i].Cost<out[j].Cost};return out[i].PeerID<out[j].PeerID});return out}
